// STEP 1 — spam/abuse filter, before anything costs money.
// Blocked messages are dropped here and never classified, never queued, never shown on
// the public rail. The backend repeats this check: n8n is not the only door to /chat-in.
const BLOCK = ['fuck','bitch','whore','nigger','retard','זונה','שרמוטה'];
const wh = $('Webhook').first().json;
const body = (wh && wh.body) || $input.first().json.body || $input.first().json;
const raw = body.messages || [];

const clean = [];
for (const m of raw) {
  let text = String(m.text || '').trim();
  if (!text) continue;
  const low = text.toLowerCase();
  if (BLOCK.some(w => low.includes(w))) continue;                  // abuse -> drop
  text = text.replace(/https?:\/\/\S+|www\.\S+/gi, '').trim();     // link-strip -> no promo spam
  text = text.replace(/(.)\1{6,}/g, '$1$1$1');                     // repeat-collapse
  if (!text) continue;
  clean.push({ ...m, text: text.slice(0, 300) });
}
if (!clean.length) return [];
return [{ json: { messages: clean } }];

// STEP 3+4 — priority order and same-question dedupe.
// Priority: buy_intent > product/price questions > greeting. noise NEVER reaches Maya —
// a host who answers 'lol' looks like a bot; one who answers the buyer first sells.
// Dedupe: three viewers asking the same thing become ONE answer naming all three, which
// is also the single most human-looking thing she does.
const PRIORITY = { buy_intent: 0, question_shipping_price: 1, question_product: 2, greeting: 3 };
const msgs = $('Filter spam/abuse').first().json.messages;

let results = [];
try {
  const content = $input.first().json.choices[0].message.content;
  results = JSON.parse(content).results || [];
} catch (e) {
  // Classification failed. FAIL SAFE, NOT SILENT: treat everything as a product question
  // so real viewers still get answered, and say so in the item for the operator log.
  results = msgs.map(m => ({ msg_id: m.msg_id, klass: 'question_product', lang: 'he', degraded: true }));
}
const byId = Object.fromEntries(results.map(r => [r.msg_id, r]));

const enriched = msgs.map(m => {
  const r = byId[m.msg_id] || { klass: 'question_product', lang: 'he' };
  return { ...m, priority: r.klass, lang: r.lang || 'he', degraded: !!r.degraded };
}).filter(m => m.priority !== 'noise');

// dedupe on a normalized question body
const groups = new Map();
for (const m of enriched) {
  const key = m.text.toLowerCase().replace(/[^\p{L}\p{N} ]/gu, '').replace(/\s+/g, ' ').trim();
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(m);
}
const out = [];
for (const [, group] of groups) {
  const head = group[0];
  const names = [...new Set(group.map(g => g.name))];
  out.push({ json: { ...head,
    name: names.length > 1 ? names.slice(0, 3).join(', ') : head.name,
    asked_by: names,
    dup_count: group.length } });
}
out.sort((a, b) => (PRIORITY[a.json.priority] ?? 9) - (PRIORITY[b.json.priority] ?? 9));
return out;
